{
  "findings": [
    {
      "title": "Sample size inconsistency: synopsis states 100, statistical methods state 120",
      "page": 6,
      "quote": "The number of subjects planned for this study is 100.",
      "severity": "critical"
    },
    {
      "title": "Sample size inconsistency: statistical methods state 120",
      "page": 11,
      "quote": "The study will enroll approximately 120 subjects.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion age inconsistency: protocol states ≥21 years, but typical oncology trials use ≥18; no justification provided",
      "page": 8,
      "quote": "Age ≥ 21 years at time of consent.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 4c is contradictory: requires documented progression in previously radiated lesion to serve as target lesion, but exclusion criterion 2 allows radiation within 2 weeks; also contradicts standard RECIST that irradiated lesions cannot be target unless progressed",
      "page": 7,
      "quote": "Documented disease progression in any lesion that was previously radiated in order to serve as a target lesion.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent section: Section 99.4 for prohibited therapies",
      "page": 8,
      "quote": "Refer to Section 99.4. for prohibited therapies.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 7a: neutrophil count threshold is unusually high (≥3000/mm3) and inconsistent with common eligibility criteria (typically ≥1500/mm3)",
      "page": 7,
      "quote": "neutrophil count ≥ 3000/mm3",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 7a: white blood cell count threshold (≥2000/mm3) is lower than neutrophil threshold (≥3000/mm3), which is biologically impossible since neutrophils are a subset of WBCs",
      "page": 7,
      "quote": "white blood cells ≥ 2000/mm3",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 3b: confirmatory assessment may serve as Baseline if completed within 30 days before start of treatment, but this is inconsistent with the requirement for PD within 12 weeks of last dose; also the confirmatory assessment is not clearly defined as a new baseline scan",
      "page": 7,
      "quote": "The confirmatory assessment may serve as the Baseline for this study if completed within 30 days before the start of study treatment.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 5: allows archival sample if no intervening therapy, but also allows discussion with Medical Monitor if biopsy unsafe; this is vague and may lead to inconsistent eligibility",
      "page": 7,
      "quote": "If the Investigator believes it is unsafe to perform a biopsy, the subject may be considered eligible after discussion with the Medical Monitor if tissue and/or prior assessments are available to determine programmed death-ligand 1 expression.",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 18: prohibits blood products or colony stimulating factors within 30 days before start of Screening, but this is not a standard washout and may be overly restrictive; also inconsistent with common practice where such agents are allowed until 2 weeks before treatment",
      "page": 9,
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 30 days before the start of Screening.",
      "severity": "minor"
    },
    {
      "title": "Treatment duration: maximum of 2 years from start of treatment, but discontinuation criteria for CR require at least 48 weeks of treatment and at least 3 doses beyond initial CR; this is inconsistent with the 2-year cap if CR occurs early",
      "page": 10,
      "quote": "Treatment will be given for a maximum of 2 years from the start of study treatment.",
      "severity": "major"
    },
    {
      "title": "Pharmacokinetic assessment: states first 20 subjects enrolled, but no further detail on sampling schedule or analysis for PK in the synopsis; also PK analysis set definition is vague",
      "page": 11,
      "quote": "Pharmacokinetic assessment will be performed in order to assess serum CMP-001 levels following IT injection and potentially SC administration in the first 20 subjects enrolled.",
      "severity": "minor"
    }
  ]
}
